UPDATE CAFE_MEMBER
SET
	CAFE_ROLE = #{cafeRole}
WHERE CAFE_ID = #{cafeId}
	AND MEMBER_USERNAME = #{memberUsername}
	AND STATUS = 'ACTIVE'
	AND CAFE_ROLE != 'OWNER'

UPDATE CAFE_MEMBER
SET STATUS = 'WITHDRAWN'
WHERE CAFE_ID = #{cafeId}
  AND MEMBER_USERNAME = #{memberUsername}
  AND STATUS = 'ACTIVE'
  AND CAFE_ROLE != 'OWNER'
